1	#!/usr/bin/env node
2	// Shell execution service — runs OUTSIDE pm2 to avoid posix_spawn EBADF
3	// Communicate via HTTP on port 3098 with the nudimmud-backend
4	'use strict';
5	const http = require('http');
6	const { spawn } = require('child_process');
7	const ROOT = process.env.NUDIMMUD_ROOT || '/Users/marcelspatz/NUDIMMUD';
8	const PORT = parseInt(process.env.SHELL_SERVICE_PORT || '3098', 10);
9	const API_KEY = process.env.SHELL_SERVICE_KEY || 'nudimmud-master-key-2026-04-23';
10	const SHELL_ENV = { ...process.env, PATH: process.env.PATH || '/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin' };
11	
12	const server = http.createServer((req, res) => {
13	    if (req.method !== 'POST' || req.url !== '/run') {
14	        res.writeHead(404).end('not found');
15	        return;
16	    }
17	    if (req.headers['x-api-key'] !== API_KEY) {
18	        res.writeHead(401).end('unauthorized');
19	        return;
20	    }
21	    let body = '';
22	    req.on('data', d => body += d);
23	    req.on('end', () => {
24	        let command;
25	        try { command = JSON.parse(body).command; } catch { res.writeHead(400).end('bad json'); return; }
26	        if (typeof command !== 'string' || !command.trim()) {
27	            res.writeHead(400).end('command required');
28	            return;
29	        }
30	        res.writeHead(200, {
31	            'Content-Type': 'text/event-stream',
32	            'Cache-Control': 'no-cache',
33	            'Connection': 'keep-alive',
34	        });
35	        const send = obj => { try { res.write('data: ' + JSON.stringify(obj) + '\n\n'); } catch {} };
36	        let child;
37	        try {
38	            child = spawn('/bin/sh', ['-c', command], {
39	                cwd: ROOT, env: SHELL_ENV, stdio: ['ignore', 'pipe', 'pipe'],
40	            });
41	        } catch (e) {
42	            send({ type: 'stderr', data: e.message });
43	            send({ type: 'exit', code: 1 });
44	            res.end();
45	            return;
46	        }
47	        child.stdout.on('data', d => send({ type: 'stdout', data: d.toString() }));
48	        child.stderr.on('data', d => send({ type: 'stderr', data: d.toString() }));
49	        let done = false;
50	        child.on('error', e => { done = true; send({ type: 'stderr', data: e.message }); res.end(); });
51	        child.on('close', code => { done = true; send({ type: 'exit', code }); res.end(); });
52	        res.on('close', () => { if (!done) { try { child.kill(); } catch {} } });
53	    });
54	});
55	
56	server.listen(PORT, '127.0.0.1', () => {
57	    console.log(`nudimmud-shell-service listening on 127.0.0.1:${PORT}`);
58	});
