114	function canBindPort(port: number): Promise<boolean> {
115	    return new Promise((resolve) => {
116	        const probe = net.createServer();
117	
118	        const cleanup = () => {
119	            probe.removeAllListeners('error');
120	            probe.removeAllListeners('listening');
121	        };
122	
123	        probe.once('error', () => {
124	            cleanup();
125	            resolve(false);
126	        });
127	
128	        probe.once('listening', () => {
129	            cleanup();
130	            probe.close(() => resolve(true));
131	        });
132	
133	        try {
134	            probe.listen(port, HOST);
135	        } catch {
136	            cleanup();
137	            resolve(false);
138	        }
139	    });
140	}
