142	function listenOnPort(port: number): Promise<void> {
143	    return new Promise((resolve, reject) => {
144	        const handleError = (error: NodeJS.ErrnoException) => {
145	            server.off('listening', handleListening);
146	            reject(error);
147	        };
148	
149	        const handleListening = () => {
150	            server.off('error', handleError);
151	            resolve();
152	        };
153	
154	        server.once('error', handleError);
155	        server.once('listening', handleListening);
156	
157	        try {
158	            server.listen(port, HOST);
159	        } catch (error) {
160	            server.off('error', handleError);
161	            server.off('listening', handleListening);
162	            reject(error);
163	        }
