566	async function gracefulShutdown(signal: string) {
567	    if (shuttingDown) return;
568	    shuttingDown = true;
569	
570	    bootLog(`⬡ SHUTDOWN_SIGNAL_RECEIVED :: ${signal}`);
571	    clearTrackedTimers();
572	    guard.stop();
573	
574	    try {
575	        await vaultWatcherController?.close();
576	        bootLog('⬡ VAULT_WATCHER_STOPPED');
577	    } catch (error: any) {
578	        bootLog(`⬡ VAULT_WATCHER_STOP_ERROR: ${error.message}`);
579	    }
580	
581	    wss?.clients.forEach((client) => {
582	        if (client.readyState === 1) {
583	            client.close(1001, 'Server shutting down');
584	        }
585	    });
586	
587	    const forcedExit = setTimeout(() => {
588	        bootLog('⬡ FORCED_EXIT :: Timed out while shutting down');
589	        process.exit(1);
590	    }, 5000);
591	
592	    try {
593	        if (wss) {
594	            await new Promise<void>((resolve) => wss!.close(() => resolve()));
595	        }
596	        await new Promise<void>((resolve) => server.close(() => resolve()));
597	    } finally {
598	        clearTimeout(forcedExit);
599	    }
600	
601	    try {
602	        db.close();
603	        bootLog('⬡ DATABASE_CLOSED');
604	    } catch (error: any) {
605	        bootLog(`⬡ DATABASE_CLOSE_ERROR: ${error.message}`);
606	    }
607	
608	    process.exit(0);
609	}
610	
611	process.on('SIGTERM', () => {
612	    void gracefulShutdown('SIGTERM');
613	});
614	
615	process.on('SIGINT', () => {
616	    void gracefulShutdown('SIGINT');
