619	async function startServer() {
620	    for (let index = 0; index < PORT_CANDIDATES.length; index += 1) {
621	        const port = PORT_CANDIDATES[index];
622	        currentPort = port;
623	        const nextPort = PORT_CANDIDATES[index + 1];
624	
625	        const bindable = await canBindPort(port);
626	        if (!bindable) {
627	            if (nextPort) {
628	                bootLog(`⬡ PORT_COLLISION :: ${port} unavailable. Trying ${nextPort}...`);
629	                continue;
630	            }
631	            break;
632	        }
633	
634	        try {
635	            await listenOnPort(port);
636	            wss = new WebSocketServer({ server });
637	            attachWebSocketServer(wss);
638	
639	            server.on('error', (error: any) => {
640	                bootLog(`⬡ SERVER_ERROR: ${error.message}`);
641	            });
642	
643	            bootLog(`⬡ NUDIMMUD_BACKEND_ONLINE :: ${HOST}:${currentPort}`);
644	            logEvent(db, 'SYSTEM', 'SERVER', `Backend server started on ${HOST}:${currentPort}`, 'INFO');
645	            return;
646	        } catch (error) {
647	            if (isRecoverableListenError(error) && nextPort) {
648	                bootLog(`⬡ PORT_COLLISION :: ${port} failed during bind (${error.code}). Trying ${nextPort}...`);
649	                continue;
650	            }
651	
652	            throw error;
653	        }
654	    }
655	
656	    throw new Error(`Port exhaustion. No ports available around ${DEFAULT_PORT}.`);
657	}
658	
659	void startServer().catch((error: any) => {
660	    bootLog(`⬡ FATAL_SERVER_START_ERROR: ${error.message}`);
661	    process.exit(1);
662	});
