14	function normalizeAddress(value: string | undefined | null): string {
15	    if (!value) return '';
16	    return value.replace(/^::ffff:/, '');
17	}
18	
19	function isLoopbackAddress(value: string | undefined | null): boolean {
20	    const normalized = normalizeAddress(value);
21	    return normalized === '::1' || normalized === '127.0.0.1' || normalized.startsWith('127.');
22	}
23	
24	export function isLocalRequest(req: Request): boolean {
25	    if (isLoopbackAddress(req.ip) || isLoopbackAddress(req.socket.remoteAddress)) {
26	        return true;
27	    }
28	
29	    const origin = req.header('origin');
30	    if (!origin) return false;
31	
32	    try {
33	        const parsed = new URL(origin);
34	        return LOOPBACK_HOSTS.has(parsed.hostname);
35	    } catch {
36	        return false;
37	    }
38	}
39	
40	export function localOnlyMiddleware(req: Request, res: Response, next: NextFunction) {
41	    if (!isLocalRequest(req)) {
42	        console.warn(`⬡ SECURITY_ALERT :: Local-only route blocked for ${req.path} from ${req.ip}`);
43	        return res.status(403).json({
44	            error: 'FORBIDDEN',
45	            message: 'This endpoint is only available from the local machine.'
46	        });
47	    }
48	
49	    next();
50	}
51	
52	export function getRuntimeApiKey(): string {
53	    return RUNTIME_API_KEY;
54	}
